export const totalPlanned = 50;

export const lockedCount = architects.filter((a) => a.status === 'locked').length;
export const draftedCount = architects.filter((a) => a.status !== 'candidate').length;
export const illustratedCount = architects.filter((a) => Boolean(a.front)).length;

export const featuredArchitects = architects.filter((a) => a.status === 'locked').slice(0, 6);

export function getArchitect(slug: string) {
  return architects.find((a) => a.slug === slug);
}

export type PortraitCredit = {
  credit: string;
  license: string;
  licenseUrl?: string;
  sourceUrl?: string;
};

type RefRow = { slug: string; ref?: (PortraitCredit & { url?: string }) | null };

/**
 * Photographer credits, written by scripts/ai-refs.mjs. Same rule as Series
 * Three: every portrait is painted from a real, identified photograph, and a
 * card with no entry here has no face at all rather than an invented one.
 */
import refs from '../../data/ai-references.json' with { type: 'json' };

export function getPortraitCredit(slug: string): PortraitCredit | undefined {
  const row = (refs as RefRow[]).find((r) => r.slug === slug);
  if (!row?.ref) return undefined;
  const { credit, license, licenseUrl, sourceUrl } = row.ref;
  return { credit, license, licenseUrl, sourceUrl };
}
